def largest_shape_group(traces):
    counts = {}
    best = 0
    for t in traces:
        key = tuple(t[i + 1] - t[i] for i in range(len(t) - 1))
        counts[key] = counts.get(key, 0) + 1
        best = max(best, counts[key])
    return best

